// Lookup of the offline slip limits in slip_table.h (generated by the Octave model).
//
// sMax(W):       linear interpolation of S_MAX over wheel load. Loads outside the grid are
//                clamped to the nearest grid end.
// sMin(W, alpha): bilinear interpolation of S_MIN over load and incline [deg].
//                Load is clamped to the grid. Incline below 0 (downhill) is clamped to 0.
//                Incline above the last grid value (20 deg) returns kInfeasible: the table
//                says nothing there and clamping would understate the required slip.
//                A cell is infeasible if any corner that carries non-zero weight is -1.
//                Corners with zero weight are ignored, so exact grid points always return
//                their own table value.

#ifndef ROSEY_TRACTION__SLIP_TABLE_LOOKUP_HPP_
#define ROSEY_TRACTION__SLIP_TABLE_LOOKUP_HPP_

namespace rosey_traction
{

constexpr double kInfeasible = -1.0;

double sMax(double w);
double sMin(double w, double alpha_deg);

// Grid access for tests and diagnostics.
int tableLoadCount();
int tableAlphaCount();
double tableLoad(int i);
double tableAlpha(int j);
double tableSMax(int i);
double tableSMin(int i, int j);

}  // namespace rosey_traction

#endif  // ROSEY_TRACTION__SLIP_TABLE_LOOKUP_HPP_
